<script setup>
import {reactive,ref,computed,watch,onUnmounted} from 'vue';import {router} from '@inertiajs/vue3';
const props=defineProps({catalog:Object,filters:Object,path:{default:'/progress'},student:Number});
const form=reactive({subject:'',topic:'',difficulty:'',mode:'',from:'',to:'',...props.filters}),period=ref(props.filters.period||(props.filters.from||props.filters.to?'custom':'all')),more=ref(false),loading=ref(false);let timer;
const topics=computed(()=>[...new Set(props.catalog.topics.filter(t=>!form.subject||t.subject===form.subject).map(t=>t.topic))]);
function dates(){if(period.value==='custom')return;form.from='';form.to='';if(period.value!=='all'){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;const date=new Date(get('year')+'-'+get('month')+'-'+get('day')+'T12:00:00Z');form.to=date.toISOString().slice(0,10);date.setUTCDate(date.getUTCDate()-(Number(period.value)-1));form.from=date.toISOString().slice(0,10)}}
function apply(){if(form.from&&form.to&&form.from>form.to)return;router.get(props.path,{...form,period:period.value,...(props.student?{student:props.student}:{})},{preserveState:true,preserveScroll:true,replace:true,onStart:()=>loading.value=true,onFinish:()=>loading.value=false})}
watch(period,()=>{dates();if(period.value==='custom')more.value=true});watch(()=>form.subject,()=>form.topic='');
watch(()=>JSON.stringify([form,period.value]),()=>{clearTimeout(timer);timer=setTimeout(apply,300)});
onUnmounted(()=>clearTimeout(timer));
function reset(){Object.assign(form,{subject:'',topic:'',difficulty:'',mode:'',from:'',to:''});period.value='all'}
const chips=computed(()=>Object.entries({subject:form.subject,topic:form.topic,difficulty:form.difficulty,mode:form.mode}).filter(([,v])=>v));
</script>
<template><div class="progress-filter"><div class="progress-primary"><label>Subject<select v-model="form.subject"><option value="">All subjects</option><option v-for="s in catalog.subjects" :key="s">{{s}}</option></select></label><label>Time period<select v-model="period"><option value="all">All time</option><option value="1">Today</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="custom">Custom dates</option></select></label><button type="button" :aria-expanded="more" @click="more=!more">More filters {{more?'−':'+'}}</button></div>
<div v-if="more" class="advanced-filters"><label>Topic<select v-model="form.topic"><option value="">All topics</option><option v-for="t in topics" :key="t">{{t}}</option></select></label><label>Difficulty<select v-model="form.difficulty"><option value="">All difficulties</option><option>Easy</option><option>Average</option><option>Difficult</option></select></label><label>Study tool<select v-model="form.mode"><option value="">All study tools</option><option value="fresh">Fresh Catch</option><option value="memory">Memory Maki</option><option value="tutor">Maki Mentor</option><option value="exam">Wasabi Rush</option><option value="assigned">Assigned exams</option></select></label><template v-if="period==='custom'"><label>From<input type="date" v-model="form.from"></label><label>Through<input type="date" v-model="form.to" :min="form.from"></label></template></div>
<div class="chips"><button v-for="[key,value] in chips" :key="key" @click="form[key]=''">{{value}} ×</button><button v-if="period!=='all'" @click="period='all'">{{period==='custom'?((form.from||'Any date')+' to '+(form.to||'today')):period==='1'?'Today':'Last '+period+' days'}} ×</button><button v-if="chips.length||period!=='all'" class="plain" @click="reset">Clear all</button></div><div class="filter-status" role="status">{{form.from&&form.to&&form.from>form.to?'The end date must follow the start date.':loading?'Updating your progress…':'Accuracy follows these filters. Lifetime coverage stays visible.'}}</div></div></template>
